                fxReportParserError(parser, parser->line, "missing identifier");
                fxPushNULL(parser);
        }
        for (;;) {
                if (parser->token == XS_TOKEN_MORE)
                        break;
                if (parser->token == XS_TOKEN_DIVIDE) {
                        fxGetNextToken(parser);
